import json, os
from pathlib import Path
counts = {"processes_seen": 0, "fd_directories_readable": 0, "fd_directories_denied": 0, "processes_disappeared_or_other_error": 0}
for p in Path("/proc").iterdir():
    if not p.name.isdigit():
        continue
    counts["processes_seen"] += 1
    try:
        list((p / "fd").iterdir())
        counts["fd_directories_readable"] += 1
    except PermissionError:
        counts["fd_directories_denied"] += 1
    except OSError:
        counts["processes_disappeared_or_other_error"] += 1
print(json.dumps({"effective_uid": os.geteuid(), "visibility": counts}))
